int fb_mmap(struct file *file, struct vm_area_struct *vma)
{
    struct fb_info *info = file->private_data;
    int ret = 0;
    unsigned long offset = vma->vm_pgoff << PAGE_SHIFT;
    unsigned long size = vma->vm_end - vma->vm_start;

    if (!info || !info->screen_base)
        return -EINVAL;

    mutex_lock(&info->mmio_lock);

    if (info->fbops->fb_mmap) {
        ret = info->fbops->fb_mmap(info, vma);
        goto unlock;
    }

    if (offset < info->screen_size)
        ret = vm_insert_pages(vma, vma->vm_start,
                              info->screen_pages + offset / PAGE_SIZE,
                              size >> PAGE_SHIFT);
    else if (info->fbops->fb_ioctl && offset >= info->screen_size &&
             offset < info->screen_size + info->pixmap.size) {
        ret = -EINVAL;
        if (info->fbops->fb_ioctl)
            ret = info->fbops->fb_ioctl(info, FBIOGET_PSEUDO_PALETTE, (unsigned long)vma);
    }

unlock:
    mutex_unlock(&info->mmio_lock);
    return ret;
}

int fb_mmap(struct file *file, struct vm_area_struct *vma) {
    struct fb_info *info = file->private_data;
    struct fb_ops *ops = info->fbops;
    unsigned long offset = vma->vm_pgoff << PAGE_SHIFT;
    int ret = -EINVAL;

    if (!info || !ops || !ops->fb_mmap)
        return -EINVAL;

    mutex_lock(&info->mm_lock);

    if (ops->fb_mmap) {
        ret = ops->fb_mmap(info, vma);
        if (!ret)
            goto unlock;
    }

    if (offset < info->fix.smem_start || offset >= info->fix.smem_start + info->fix.smem_len) {
        ret = -EINVAL;
        goto unlock;
    }

    vma->vm_page_prot = pgprot_noncached(vma->vm_page_prot);
    remap_pfn_range(vma, 0, offset >> PAGE_SHIFT, vma->vm_end - vma->vm_start, vma->vm_page_prot);
    ret = 0;

unlock:
    mutex_unlock(&info->mm_lock);
    return ret;
}

int my_framebuffer_mmap(struct file *file, struct vm_area_struct *vma) {
    struct fb_info *info = file->private_data;
    struct fb_ops *fbops = info->fbops;
    unsigned long start, size;
    int ret = 0;

    if (!info || !fbops)
        return -EINVAL;

    mutex_lock(&info->mm_lock);

    if (fbops->mmap) {
        ret = fbops->mmap(info, vma);
        mutex_unlock(&info->mm_lock);
        return ret;
    }

    start = info->fix.smem_start + (vma->vm_pgoff << PAGE_SHIFT);
    size = info->fix.smem_len - ((vma->vm_pgoff << PAGE_SHIFT) + vma->vm_end - vma->vm_start);

    if (size > vma->vm_end - vma->vm_start)
        size = vma->vm_end - vma->vm_start;

    vma->vm_flags |= VM_IO | VM_RESERVED;
    vma->vm_page_prot = pgprot_writecombine(vma->vm_page_prot);

    mutex_unlock(&info->mm_lock);

    return remap_pfn_range(vma, vma->vm_start, start >> PAGE_SHIFT, size, vma->vm_page_prot);
}

int fb_mmap(struct file *file, struct vm_area_struct *vma) {
    struct fb_info *info = file->private_data;
    int ret = 0;

    if (!info || !info->screen_base)
        return -EINVAL;

    mutex_lock(&info->mm_lock);

    if (info->fbops->fb_mmap) {
        ret = info->fbops->fb_mmap(info, vma);
        goto unlock;
    }

    {
        unsigned long start_pg = vma->vm_start;
        unsigned long size = vma->vm_end - vma->vm_start;
        unsigned long start = info->fix.smem_start;
        unsigned long len = info->fix.smem_len;

        if ((vma->vm_pgoff << PAGE_SHIFT) < start)
            vma->vm_flags |= VM_IO;

        start += vma->vm_pgoff << PAGE_SHIFT;
        if (start >= (start + size))
            len = 0;
        else if ((start + size) > (start + len))
            size = start + len - start;
        else
            len = size;

        vma->vm_flags |= VM_IO | VM_DONTEXPAND | VM_PFNMAP;
        vma->vm_page_prot = pgprot_noncached(vma->vm_page_prot);

        if (remap_pfn_range(vma, start_pg, start >> PAGE_SHIFT,
                            size, vma->vm_page_prot)) {
            ret = -EAGAIN;
        }
    }

unlock:
    mutex_unlock(&info->mm_lock);
    return ret;
}

#include <linux/fb.h>
#include <linux/mm.h>
#include <linux/mutex.h>

int fb_mmap(struct file *file, struct vm_area_struct *vma)
{
    struct fb_info *info = file->private_data;
    struct fb_ops *fbops = info->fbops;
    unsigned long start, size;
    int ret = 0;

    if (!info || !fbops)
        return -EINVAL;

    mutex_lock(&info->mmio_lock);

    if (fbops->mmap) {
        ret = fbops->mmap(info, vma);
        goto out;
    }

    start = (unsigned long)info->screen_base;
    size = PAGE_ALIGN((unsigned long)info->screen_size);

    if ((vma->vm_pgoff << PAGE_SHIFT) < info->screen_size) {
        start += (vma->vm_pgoff << PAGE_SHIFT);
        size = min(size - (vma->vm_pgoff << PAGE_SHIFT), vma->vm_end - vma->vm_start);
    } else {
        start = info->mmio_start + (vma->vm_pgoff << PAGE_SHIFT);
        size = min(info->mmio_start - start + info->mmio_length, vma->vm_end - vma->vm_start);
    }

    vma->vm_page_prot = pgprot_noncached(vma->vm_page_prot);
    ret = remap_pfn_range(vma, vma->vm_start, start >> PAGE_SHIFT, size, vma->vm_page_prot);

out:
    mutex_unlock(&info->mmio_lock);
    return ret;
}
